head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[tabControl > E > onaftertabmove]<br/>tabMove=true 일때 Tab 버튼을 DragDrop 하여 Tab 페이지의 순서가 변경된 후 발생합니다.",
    "validation" : [
        "onbeforetabmove 이벤트에서 false 를 반환한 경우 onaftertabmove 이벤트는 발생하지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        tabMove : true,
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onbeforetabmove", "onaftertabmove"]);

    $c.gcm.createBasicTabControl(cList, eList);

    scwin.getTabButtonInfo();
}




scwin.target1_onbeforetabmove = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onbeforetabmove=====");
    return false;
}



scwin.target1_onaftertabmove = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onaftertabmove=====");
    wf_body_bottom.getObj("scwin").setReturnValue("info.startTabIndex : " + info.startTabIndex);
    wf_body_bottom.getObj("scwin").setReturnValue("info.startTabID : " + info.startTabID);
    wf_body_bottom.getObj("scwin").setReturnValue("info.endTabID : " + info.endTabID);
    wf_body_bottom.getObj("scwin").setReturnValue("info.endTabIndex : " + info.endTabIndex);
}
